import { BufferGeometry, Color, Float32BufferAttribute, ShapeUtils, Vector2 } from 'three';
import type { Atlas } from '../shared/countries.js';

type Triangle = [Vector2, Vector2, Vector2];

/** The atlas contains closed, straight SVG rings generated by d3-geo. */
export function atlasRings(path: string): Vector2[][] {
  const rings: Vector2[][] = [];
  let ring: Vector2[] = [];
  for (const match of path.matchAll(/([ML])([^MLZ]+)/g)) {
    if (match[1] === 'M') {
      ring = [];
      rings.push(ring);
    }
    const [x, y] = match[2]!.split(',').map(Number);
    if (!Number.isFinite(x) || !Number.isFinite(y)) throw new Error('Invalid atlas coordinate');
    ring.push(new Vector2(x, y));
  }
  return rings.filter(points => points.length >= 3);
}

function sphericalPoint(point: Vector2, width: number, height: number, radius: number): number[] {
  const longitude = (point.x / width * 2 - 1) * Math.PI;
  const latitude = (.5 - point.y / height) * Math.PI;
  return [radius * Math.cos(latitude) * Math.cos(longitude), radius * Math.sin(latitude),
    -radius * Math.cos(latitude) * Math.sin(longitude)];
}

export function countrySurface(path: string, width: number, height: number): { positions: number[]; indices: number[] } {
  const groups: { outline: Vector2[]; holes: Vector2[][] }[] = [];
  // d3 emits each exterior ring followed by its oppositely wound holes.
  for (const ring of atlasRings(path)) {
    if (ShapeUtils.area(ring) > 0) groups.push({ outline: ring, holes: [] });
    else groups.at(-1)?.holes.push(ring);
  }
  const positions: number[] = [];
  const indices: number[] = [];
  const vertices = new Map<string, number>();
  const maxEdgeSquared = (width / 90) ** 2;
  for (const { outline, holes } of groups) {
    const faces = ShapeUtils.triangulateShape(outline, holes);
    const points = [...outline, ...holes.flat()];
    const pending: Triangle[] = faces.map(face => [points[face[0]!]!, points[face[1]!]!, points[face[2]!]!]);
    while (pending.length) {
      const [a, b, c] = pending.pop()!;
      const ab = a.distanceToSquared(b), bc = b.distanceToSquared(c), ca = c.distanceToSquared(a);
      if (Math.max(ab, bc, ca) <= maxEdgeSquared) {
        for (const point of [a, c, b]) {
          const key = `${point.x},${point.y}`;
          let index = vertices.get(key);
          if (index === undefined) {
            index = positions.length / 3;
            vertices.set(key, index);
            positions.push(...sphericalPoint(point, width, height, 1.001));
          }
          indices.push(index);
        }
      } else if (ab >= bc && ab >= ca) {
        const midpoint = a.clone().add(b).multiplyScalar(.5);
        pending.push([a, midpoint, c], [midpoint, b, c]);
      } else if (bc >= ca) {
        const midpoint = b.clone().add(c).multiplyScalar(.5);
        pending.push([a, b, midpoint], [a, midpoint, c]);
      } else {
        const midpoint = c.clone().add(a).multiplyScalar(.5);
        pending.push([a, b, midpoint], [midpoint, b, c]);
      }
    }
  }
  return { positions, indices };
}

export function atlasBorders(atlas: Atlas): number[] {
  const positions: number[] = [];
  const seen = new Set<string>();
  for (const item of [...atlas.context, ...atlas.countries]) {
    for (const ring of atlasRings(item.path)) {
      for (let index = 0; index < ring.length; index++) {
        const a = ring.at(index)!, b = ring.at((index + 1) % ring.length)!;
        // The map's clipping edges are not real borders on the globe.
        if (a.x === b.x && (a.x === 0 || a.x === atlas.width)
          || a.y === b.y && (a.y === 0 || a.y === atlas.height)) continue;
        const first = `${a.x},${a.y}`, second = `${b.x},${b.y}`;
        const key = first < second ? `${first}:${second}` : `${second}:${first}`;
        if (seen.has(key)) continue;
        seen.add(key);
        const steps = Math.max(1, Math.ceil(a.distanceTo(b) / (atlas.width / 720)));
        for (let step = 0; step < steps; step++) {
          const from = a.clone().lerp(b, step / steps), to = a.clone().lerp(b, (step + 1) / steps);
          positions.push(...sphericalPoint(from, atlas.width, atlas.height, 1.0015),
            ...sphericalPoint(to, atlas.width, atlas.height, 1.0015));
        }
      }
    }
  }
  return positions;
}

export class GlobeSurface {
  readonly geometry = new BufferGeometry();
  private ranges = new Map<string, { start: number; count: number }>();
  private color = new Color();
  private colors: Float32BufferAttribute;

  constructor(atlas: Atlas) {
    const positions: number[] = [], colors: number[] = [], indices: number[] = [];
    for (const item of [...atlas.context, ...atlas.countries]) {
      const surface = countrySurface(item.path, atlas.width, atlas.height);
      const start = positions.length;
      this.color.set('id' in item ? '#667273' : '#515b65');
      for (let index = 0; index < surface.positions.length; index += 3) {
        positions.push(surface.positions.at(index)!, surface.positions.at(index + 1)!, surface.positions.at(index + 2)!);
        colors.push(this.color.r, this.color.g, this.color.b);
      }
      for (const index of surface.indices) indices.push(index + start / 3);
      if ('id' in item && typeof item.id === 'string') this.ranges.set(item.id, { start, count: surface.positions.length });
    }
    this.geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    this.geometry.setIndex(indices);
    const normals = Float32Array.from(positions, value => value / 1.001);
    this.geometry.setAttribute('normal', new Float32BufferAttribute(normals, 3));
    this.colors = new Float32BufferAttribute(colors, 3);
    this.geometry.setAttribute('color', this.colors);
    this.geometry.computeBoundingSphere();
  }

  paint(id: string, color: string): void {
    const range = this.ranges.get(id);
    if (!range) return;
    this.color.set(color);
    for (let index = range.start; index < range.start + range.count; index += 3) {
      this.colors.setXYZ(index / 3, this.color.r, this.color.g, this.color.b);
    }
    this.colors.addUpdateRange(range.start, range.count);
    this.colors.needsUpdate = true;
  }
}
